import{c as t,Q as a,j as r,m as o}from"./chunks/framework.DK3sgdKX.js";const h=JSON.parse('{"title":"Events, adapters, and plugin security boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"EVENTS_AND_PLUGINS.md","filePath":"EVENTS_AND_PLUGINS.md","lastUpdated":1787235170000}'),i={name:"EVENTS_AND_PLUGINS.md"};function s(n,e,d,c,l,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="events-adapters-and-plugin-security-boundaries" tabindex="-1">Events, adapters, and plugin security boundaries <a class="header-anchor" href="#events-adapters-and-plugin-security-boundaries" aria-label="Permalink to &quot;Events, adapters, and plugin security boundaries&quot;">​</a></h1><p>Current event, adapter, and plugin boundaries. Future migrations and gates are tracked in <code>EDITOR_IMPLEMENTATION_TODO.md</code>.</p><h2 id="eventbus-src-game-events-py" tabindex="-1">EventBus (<code>src/game/events.py</code>) <a class="header-anchor" href="#eventbus-src-game-events-py" aria-label="Permalink to &quot;EventBus (`src/game/events.py`)&quot;">​</a></h2><ul><li>Typed <code>Event(type, source, frame, payload)</code>; main-thread queue only.</li><li><code>emit</code> enqueues; <code>dispatch()</code> drains FIFO in subscription order (type subscribers first, then <code>&quot;*&quot;</code> wildcards). Handler exceptions are isolated and recorded in <code>bus.errors</code>.</li><li>Queue overflow drops the oldest event (<code>bus.dropped</code>); <code>close()</code> is idempotent and rejects further emits.</li><li>Adapters (<code>src/game/adapters.py</code>) are the only sanctioned way to bring external input into the bus.</li></ul><h2 id="security-boundaries-and-non-goals" tabindex="-1">Security boundaries and non-goals <a class="header-anchor" href="#security-boundaries-and-non-goals" aria-label="Permalink to &quot;Security boundaries and non-goals&quot;">​</a></h2><ul><li>Network-facing or untrusted code SHOULD run out-of-process; the in-process <code>UDPAdapter</code> is for trusted localhost integration and demos.</li><li>Payloads are treated as untrusted data: they are never evaluated, imported, or executed. Malformed datagrams are counted, not fatal.</li><li>The EventBus does not perform authentication, rate limiting, or transport encryption. Those belong to the adapter or an out-of-process gateway.</li><li>Plugin manifests are declarative JSON: no code execution at discovery. Activation runs project code intentionally; failure is isolated per plugin.</li><li>The M7 test suite does not open remote sockets (UDP tests bind 127.0.0.1 with an ephemeral port).</li></ul><h2 id="plugin-sdk-src-editor-plugin-sdk-py" tabindex="-1">Plugin SDK (<code>src/editor/plugin_sdk.py</code>) <a class="header-anchor" href="#plugin-sdk-src-editor-plugin-sdk-py" aria-label="Permalink to &quot;Plugin SDK (`src/editor/plugin_sdk.py`)&quot;">​</a></h2><ul><li><code>PluginManifest</code> with <code>api_version</code>; registries reject mismatches and duplicate ids. Activation failures mark the plugin <code>failed</code> without affecting others.</li><li>Discovery scans <code>plugins/*.pystg-plugin.json</code>. Python entry-point discovery is declared but not exercised by tests.</li><li>Contributions (resource types, node types, Inspector editors, commands, adapters, ...) are declared in the manifest; core registries are never patched by the sample plugin.</li></ul><h2 id="hardening" tabindex="-1">Hardening <a class="header-anchor" href="#hardening" aria-label="Permalink to &quot;Hardening&quot;">​</a></h2><ul><li>Autosave writes atomic <code>&lt;name&gt;.autosave.json</code> sidecars; recovery never overwrites the original document.</li><li>Corrupt JSON raises a structured error and leaves the file untouched.</li><li>Workspace <code>save_layout</code>/<code>restore_layout</code> persist dock/tab state and open document paths.</li><li>Migration fixtures live in <code>docs/schemas/fixtures/</code> (one per released schema version).</li></ul>',10)])])}const g=t(i,[["render",s]]);export{h as __pageData,g as default};
